/* Fades the moby in (state 1), holds until its owner is gone or dying (state 2), fades it out (state 3) and removes
 * it (state 4), easing its scale toward the class scale and spinning it all the while.
 * Adapted from Lombyte's project (GPL-3.0) for PAL: overlays/l13/gameplay/entities/002c13b0.c, FUN_L13_002e84d8. */
void update_owner_linked_class_160_moby(struct Moby *moby) {
    int *d = (int *)moby->pvars;
    int old;
    int step;

    switch (moby->state) {
    case 0:
        moby->collision = moby->pclass->collision;
        moby->state = 1;
        break;
    case 1: {
        float fade = frame_scale_r * 0.02f;
        moby->scale +=
            (moby->pclass->scale * 4.0f - moby->scale) * 0.1f;
        ((float *)d)[1] += fade;
        if (((float *)d)[1] >= 1.0f) {
            ((float *)d)[1] = 1.0f;
            moby->state = 2;
        }
        moby->alpha = truncate_float_to_s32_r(((float *)d)[1] * 60.0f);
        break;
    }
    case 2:
        moby->scale +=
            (moby->pclass->scale * 4.0f - moby->scale) * 0.1f;
        if (d[0] == 0 || ((unsigned char *)d[0])[0x20] == 0xFE || ((unsigned char *)d[0])[0x20] == 0xFD) {
            moby->state = 3;
        }
        break;
    case 3: {
        float fade = frame_scale_r * 0.02f;
        moby->scale +=
            (moby->pclass->scale - moby->scale) * 0.1f;
        ((float *)d)[1] -= fade;
        if (((float *)d)[1] <= 0.0f) {
            ((float *)d)[1] = 0.0f;
            moby->state = 4;
        }
        moby->alpha = truncate_float_to_s32_r(((float *)d)[1] * 60.0f);
        break;
    }
    case 4:
        DeleteMoby_r2(moby);
        return;
    }
    old = d[2];
    step = -0x40;
    d[2] = old + step;
    if (d[2] > 0x1000) {
        step = -0x1040;
        d[2] = old + step;
    } else if (d[2] < 0) {
        step = 0xFC0;
        d[2] = old + step;
    }
    offset_moby_class_point_pairs_r((unsigned char *)moby->pclass, 0, step);
}
