/* Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/l13/gameplay/entities/002c13b0.c, FUN_L13_002e9408. */
int update_moby_path_following_away_from_hero(struct Moby *m, char *d, int idx, int aim) {
    char *path = walker_paths[*(int *)(&d[idx << 2] + 0xB0)];
    int r = 0;
    float ahead[4];
    float behind[4];
    float a, b;
    int n;
    int k;
    int dir;
    if (path != 0) {
        n = *(short *)(d + 0x9C) + 1;
        if (n >= *(int *)path) {
            n = 0;
        }
        qcopy(ahead, path + n * 16 + 0x10);
        a = FastVecDist(ahead, gHeroPos);
        k = *(short *)(d + 0x9C) - 1;
        if (k < 0) {
            k = *(int *)path - 1;
        }
        qcopy(behind, path + k * 16 + 0x10);
        b = FastVecDist(behind, gHeroPos);
        if (a < b) {
            dir = -1;
        } else if (b < a) {
            dir = 1;
        } else {
            dir = d[0x10C] == 1 ? 1 : -1;
        }
        if (dir != (signed char)d[0x10C]) {
            float k = frame_scale;
            *(float *)(d + 0xAC) *= k * -0.100000024f + 1.0f;
            if (*(float *)(d + 0xAC) < k * 0.15f) {
                short cur = *(short *)(d + 0x9C);
                d[0x10C] = dir;
                *(short *)(d + 0x9C) = *(unsigned short *)(d + 0x9E);
                *(short *)(d + 0x9E) = cur;
            }
        } else {
            float dist = FastVecDist(&m->pos, gHeroPos);
            float s = 1.0f;
            float sp;
            if (m->command == 4) {
                s = 3.0f;
            }
            sp = *(float *)(d + 0xAC);
            sp += (s * 30.0f / dist - sp) * (frame_scale * 0.12f);
            *(float *)(d + 0xAC) = sp;
            if (sp < 0.0f) {
                *(float *)(d + 0xAC) = 0.0f;
            }
        }
        r = advance_moby_along_selected_path(m, d, idx, aim);
    }
    if (0.0f < *(float *)(path + (*(short *)(d + 0x9C) << 4) + 0x1C)) {
        r |= 2;
    }
    return r;
}
