/* Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/l13/gameplay/entities/002c13b0.c, FUN_L13_002e97e0. */
void begin_starfighter_death_sequence(struct Moby *moby, char *vars, int *result) {
    int path_ids = (int)vars + 0xB0;
    struct Moby *mobys;
    float dx;
    float dy;
    float dz;
    float horizontal;
    float scale;
    char *velocity;

    *result = 0;
    moby->flags &= 0xEFFF;
    SetDeathBits_r2(moby, 0, -1);
    vars[0x67] = 0x78;
    RerollEffectCounter(moby, (short *)(vars + 0x60));
    vars[0x13B] = 4;
    scale = g_frame_time * 10.0f;
    velocity = gemlik_scene_points + (*(int *)(vars + 0x130) << 7);
    *(short *)(vars + 0x9C) = 0;
    vec_scale_to_length(vars + 0x70, velocity, scale);
    {
        int index = *(short *)(vars + 0x9C);
        int *path_id = (int *)path_ids + (unsigned char)vars[0x13B];
        char *path = walker_paths[*path_id];
        char *point;
        char *next;

        qcopy(&moby->pos, (char *)((unsigned int)(index * 16 + 0x10) + (unsigned int)path));
        point = (char *)((int)path + index * 16);
        next = path + ++index * 16;
        dx = *(float *)(next + 0x10) - *(float *)(point + 0x10);
        dy = *(float *)(next + 0x14) - *(float *)(point + 0x14);
        moby->rot.z = fast_atan2(dx, dy);
    }
    {
        int index = *(short *)(vars + 0x9C);
        int *path_id = (int *)path_ids + (unsigned char)vars[0x13B];
        char *path = walker_paths[*path_id];
        int point = index * 16 + 0x10;
        int next = index * 16 + 0x20;

        horizontal = vec_distance_xy(path + point, path + next);
    }
    {
        int index = *(short *)(vars + 0x9C);
        char *path;
        char *point;
        char *next;

        path_ids += (unsigned char)vars[0x13B] * 4;
        path = walker_paths[*(int *)path_ids];
        next = path + (index + 1) * 16;
        point = path + index * 16;
        dz = *(float *)(next + 0x18) - *(float *)(point + 0x18);
        moby->rot.y = -fast_atan2(horizontal, dz);
    }
    vars[0x10C] = 1;
    mobys = (struct Moby *)gemlik_moby_array_start;
    mobys[*(int *)(vars + 0x134)].flags |= 2;
    mobys[*(int *)(vars + 0x134)].flags |= 1;
    mobys[*(int *)(vars + 0x134)].visible = 0;
    activate_descriptor(*(int *)(vars + 0x12C));
    moby->state = 7;
    *(float *)(vars + 0xAC) = g_frame_time * 80.0f;
    *(int *)(vars + 0xF8) = scale_ticks(600);
    queue_starfighter_voice_line(moby, (unsigned char *)vars, 0x22, 1);
    *(short *)(vars + 0x138) = 0;
    vars[0x148] = 0;
    if (*(int *)(vars + 0x104) != -1) {
        Hud_SetBarValueById(*(int *)(vars + 0x104), 0);
        *(int *)(vars + 0x104) = -1;
    }
    *(int *)(vars + 0x13C) = -1;
}
